use serde_json::{Value, json};

use super::*;
use crate::node_config::NodeHooks;
use rust_cli_kernel_api::hooks::HookEventName;

/// Generated by Node `identifyWorkspaceHookScriptPath` with an explicit platform (linux and win32).
const GOLDEN: &str = include_str!("../../cli/tests/fixtures/workspace-hook-script-paths.json");

/// `None` for a declaration the schema rejects (an empty command): it never reaches identification.
fn node_hook(hook: &Value) -> Option<NodeHook> {
    let (hooks, warnings) = NodeHooks::from_json(&json!({"events": {"Stop": [{"hooks": [hook]}]}}));
    warnings
        .is_empty()
        .then(|| hooks.matchers(HookEventName::Stop)[0].hooks[0].clone())
}

#[test]
fn script_paths_match_the_node_golden() {
    let cases: Vec<Value> = serde_json::from_str(GOLDEN).unwrap();
    assert!(cases.len() > 100);
    for case in &cases {
        let windows = case["platform"] == "win32";
        let expected = case["path"].as_str().map(str::to_owned);
        let actual = node_hook(&case["hook"]).and_then(|hook| script_path(&hook, windows));
        assert_eq!(actual, expected, "{case}");
    }
}

#[test]
fn extname_follows_node() {
    for (path, ext) in [
        ("x.sh", ".sh"),
        ("x.", "."),
        (".hidden", ""),
        ("..", ""),
        ("...", "."),
        ("..x", ".x"),
        ("a/b.c/d", ""),
        ("dir/x.js/", ".js"),
        ("x", ""),
    ] {
        assert_eq!(extname(path, false), ext, "{path}");
    }
    assert_eq!(extname(r"bin\tool.exe", true), ".exe");
    assert_eq!(extname(r"bin.d\tool", true), "");
}

#[test]
fn unavailable_is_any_state_but_a_file() {
    let entry = |state| ScriptEntry {
        path: "x.sh".into(),
        state,
    };
    assert!(!entry(ScriptState::File("ab".into())).unavailable());
    assert!(entry(ScriptState::Missing).unavailable());
    assert!(entry(ScriptState::Unverifiable).unavailable());
}
